#include "sfm_model_geometry.h"
#include "parallel_geometry_deformation.h"
#include <fstream>
#include <iostream>
#include <iomanip>
std::vector<uint8_t>read(const std::string&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("fixture missing");return {(std::istreambuf_iterator<char>(f)),{}};}
int main(int argc,char**argv){try{
 static_assert(sizeof(void*)==8,"x64 required");if(argc!=4)throw std::runtime_error("model base reference output OBJ required");std::string base=argv[1];auto mdl=read(base+".mdl"),vvd=read(base+".vvd"),vtx=read(base+".dx90.vtx");auto model=readSfmModelGeometryCandidate(mdl,vvd,vtx);std::vector<uint8_t>wire;auto append=[&](uint32_t v){auto p=reinterpret_cast<const uint8_t*>(&v);wire.insert(wire.end(),p,p+4);};size_t triangles=0;for(auto&m:model.meshes){append(m.body);append(m.model);append(m.mesh);append(uint32_t(m.material));append(uint32_t(m.triangles.size()));for(auto&t:m.triangles)for(auto v:t)append(v);triangles+=m.triangles.size();}if(wire!=read(argv[2])||model.meshes.size()!=21||model.geometry.vertices.size()!=47850||model.bones.size()!=92)throw std::runtime_error("model mapping differential");
 unsigned rejected=0;for(int scenario=0;scenario<4;++scenario){auto a=mdl,b=vvd,c=vtx;uint32_t value=scenario==0?0:1;if(scenario==0)std::memcpy(a.data()+76,&value,4);if(scenario==1)std::memcpy(a.data()+8,&value,4);if(scenario==2)std::memcpy(b.data()+48,&value,4);if(scenario==3)std::memcpy(c.data()+16,&value,4);bool failed=false;try{readSfmModelGeometryCandidate(a,b,c);}catch(const std::runtime_error&){failed=true;}if(!failed)throw std::runtime_error("invalid asset accepted");++rejected;}
 std::vector<GeometryMatrixCandidate>locals;for(auto&b:model.bones)locals.push_back(b.local);for(size_t n=0;n<model.bones.size();++n)if(model.bones[n].parent<0)locals[n][3]+=10;auto palette=evaluateGeometryPosePaletteCandidate(model.bones,locals);auto vertices=deformGeometryBatchCandidate(model.geometry,palette,4);
 std::ofstream out(argv[3]);if(!out)throw std::runtime_error("output open");out<<std::setprecision(9)<<"# x64 diagnostic root translated +10 X, all alternatives, no materials\n";for(auto&v:vertices)out<<"v "<<v.position[0]<<' '<<v.position[1]<<' '<<v.position[2]<<'\n';for(auto&v:vertices)out<<"vt "<<v.uv[0]<<' '<<v.uv[1]<<'\n';for(auto&v:vertices)out<<"vn "<<v.normal[0]<<' '<<v.normal[1]<<' '<<v.normal[2]<<'\n';for(auto&m:model.meshes){out<<"g body_"<<m.body<<"_model_"<<m.model<<"_mesh_"<<m.mesh<<'\n';for(auto&t:m.triangles){out<<"f";for(auto v:t){auto index=v+1;out<<' '<<index<<'/'<<index<<'/'<<index;}out<<'\n';}}out.close();if(!out)throw std::runtime_error("output write");std::cout<<"x64 integrated model mapping/deformation passed vertices="<<vertices.size()<<" triangles="<<triangles<<" rejected="<<rejected<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
